"""Generated and minified files must not be reviewed — or hidden.

From a teammate's review of a real run: it sat for hours on `tf.min.js`
(a million characters of minified TensorFlow) and three HTML files that were
Jupyter output (2.3 million characters). The model cannot say anything
useful about either.

The criterion they asked for is deliberately NOT a list of filenames, which
goes stale, but "does this read like code a human wrote" — so it catches the
next bundle nobody thought of. And a skip must be REPORTED, never silent.
"""

import pytest

from code_review_mcp.config import looks_generated
from code_review_mcp.repo_ingest import collect_files
from code_review_mcp.review import (_build_report, render_markdown,
                                    split_content_with_lines)

# Minified: one enormous line, exactly what defeats a line-based chunker.
MINIFIED = "var a=1;function b(c){return c*2}" * 3000
NOTEBOOK_HTML = (
    "<!DOCTYPE html>\n<html>\n<head><meta charset=\"utf-8\">\n"
    "<!-- Generated by nbconvert from analysis.ipynb -->\n"
    + "<div class='output'>x</div>\n" * 2000
)


# ---------- what counts as generated ----------

def test_minified_bundle_is_recognised():
    reason = looks_generated("tf.min.js", MINIFIED)
    assert reason and "minified or generated" in reason


def test_notebook_export_is_recognised_by_its_own_header():
    reason = looks_generated("analysis.html", NOTEBOOK_HTML)
    assert reason and "nbconvert" in reason


@pytest.mark.parametrize("marker", [
    "// @generated by protoc",
    "# DO NOT EDIT — this file is maintained by terraform",
    "// Code generated by mockgen. DO NOT EDIT.",
    "/* auto-generated, changes will be lost */",
])
def test_files_that_announce_themselves_are_taken_at_their_word(marker):
    reason = looks_generated("thing.go", marker + "\n" + "x = 1\n" * 50)
    assert reason and "generated file" in reason


def test_a_source_map_reference_marks_a_bundle():
    assert looks_generated("app.js", "//# sourceMappingURL=app.js.map\nlet a=1;\n")


# ---------- what must NOT be caught (the expensive mistake) ----------

def test_ordinary_source_is_left_alone():
    """Skipping a file a human wrote is worse than reviewing a generated one."""
    source = "".join(
        f"def function_{i}(argument):\n"
        f"    \"\"\"Do something useful with {i}.\"\"\"\n"
        f"    return argument * {i}\n\n"
        for i in range(400))
    assert len(source) > 20_000            # big enough to be a candidate
    assert looks_generated("service.py", source) is None


def test_one_long_line_in_real_source_is_not_minification():
    """A wide data table or a long string constant is still human code."""
    long_line = "TABLE = " + repr(list(range(400))) + "\n"
    source = ("import x\n" * 2500) + long_line
    assert len(source) > 20_000                  # past the size gate
    assert len(long_line) > 1_000                # and genuinely a long line
    # Still not flagged: one long line among thousands of short ones keeps
    # the mean low, which is what separates a data table from minification.
    assert looks_generated("tables.py", source) is None


def test_small_dense_files_are_reviewed():
    """A short one-liner is config, not a bundle — and cheap to review."""
    assert looks_generated("config.json", '{"a":1,"b":2,"c":[1,2,3]}') is None


def test_minified_html_and_css_are_caught_too():
    assert looks_generated("style.min.css", "a{color:red}" * 3000)


# ---------- the skip is recorded, never silent ----------

def test_ingest_records_a_generated_skip_with_its_reason(tmp_path):
    (tmp_path / "app.py").write_text("print('hello')\n", encoding="utf-8")
    (tmp_path / "tf.min.js").write_text(MINIFIED, encoding="utf-8")

    result = collect_files(tmp_path)

    assert [f["path"] for f in result["files"]] == ["app.py"]
    skipped = {s["path"]: s["reason"] for s in result["skipped"]}
    assert "tf.min.js" in skipped
    assert "minified" in skipped["tf.min.js"]


def test_the_skip_can_be_turned_off(tmp_path, monkeypatch):
    from code_review_mcp import repo_ingest
    monkeypatch.setattr(repo_ingest.settings, "skip_generated", False)
    (tmp_path / "tf.min.js").write_text(MINIFIED, encoding="utf-8")

    result = collect_files(tmp_path)
    assert [f["path"] for f in result["files"]] == ["tf.min.js"]
    assert result["skipped"] == []


def test_the_report_names_skipped_files_and_says_why():
    """The honest-coverage rule: a count in the header is not enough — a
    reader must be able to see that the file they care about was skipped."""
    report = _build_report(
        {"repo_url": "https://github.com/o/r", "commit": "abc",
         "skipped": [{"path": "static/tf.min.js",
                      "reason": "minified or generated (longest line 96,000 chars)"}],
         "excluded": {"count": 0, "by_type": {}, "examples": []}},
        [{"file": "app.py", "issues": [], "score": 8}], failures=[])

    assert report["stats"]["files_skipped"] == 1
    markdown = render_markdown(report)
    assert "1 file(s) were skipped" in markdown
    assert "static/tf.min.js" in markdown
    assert "minified or generated" in markdown


# ---------- the chunker must survive one anyway ----------

def test_a_single_enormous_line_is_split_instead_of_sent_whole():
    """Even when a bundle is reviewed on purpose, it must not arrive as one
    request. Line-boundary splitting alone produced ONE chunk ten times over
    budget, because a minified file has no line boundaries to split on."""
    budget = 48_000
    one_line = "var a=1;" * 60_000          # 480 KB, zero newlines
    chunks = split_content_with_lines(one_line, budget)

    assert len(chunks) > 1
    assert max(len(c) for _, c in chunks) <= budget
    assert "".join(c for _, c in chunks) == one_line      # lossless
    assert all(start == 1 for start, _ in chunks)         # all still line 1


def test_normal_files_still_chunk_on_line_boundaries():
    content = "".join(f"line {i}\n" for i in range(5000))
    chunks = split_content_with_lines(content, 4000)

    assert "".join(c for _, c in chunks) == content
    assert all(c.endswith("\n") for _, c in chunks)       # never mid-line
    starts = [s for s, _ in chunks]
    assert starts == sorted(starts) and starts[0] == 1
